# Re-fetch all group expenses for all groups to find yesterday's expenses
all_group_expenses = {}
for g in groups:
    gid = g['group_id']
    exp = apis.splitwise.show_group_expenses(access_token=splitwise_login['access_token'], group_id=gid)
    all_group_expenses[gid] = exp
    print(f"Group {gid} ({g['name']}): {len(exp)} expenses")
    for e in exp:
        print(f"  expense_id={e['expense_id']}, desc={e['description']}, created_at={e.get('created_at')}, deleted={e.get('deleted')}")

