# Let's fetch expenses for all 10 groups to find expenses created yesterday
all_groups_list = all_groups  # from previous call
all_expenses_all_groups = {}
for g in all_groups_list:
    gid = g['group_id']
    exps = apis.splitwise.show_group_expenses(access_token=splitwise_login['access_token'], group_id=gid)
    all_expenses_all_groups[gid] = exps
    # Print expenses created yesterday
    for exp in exps:
        if exp['created_at'].startswith('2023-05-19'):
            print(f"Group {gid} ({g['name']}) | Expense {exp['expense_id']} | {exp['description']} | created: {exp['created_at']} | paid_by: {exp['payer']['name']} | amount: {exp['paid_amount']}")

