    all_expenses_all_groups[gid] = exps
    # Print expenses created yesterday
    for exp in exps:
        if exp['created_at'].startswith('2023-05-19'):
            print(f"Group {gid} ({g['name']}) | Expense {exp['expense_id']} | {exp['description']} | created: {exp['created_at']} | paid_by: {exp['payer']['name']} | amount: {exp['paid_amount']}")

